H ROW EXECUTE FUNCTION platform_private.guard_sandbox_period_confirmation()"}],"functions":[{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.apply_current_subscription_refund(uuid)","definition":"CREATE OR REPLACE FUNCTION platform_private.apply_current_subscription_refund(p_request_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare r public.subscription_refund_requests%rowtype; b public.subscription_refund_period_bindings%rowtype;\n f public.billing_sandbox_refunds%rowtype; s public.organization_subscriptions%rowtype;\n a public.subscription_refund_applications%rowtype; previous jsonb; free_id uuid;\nbegin\n perform platform_private.require_sandbox_environment();\n select * into r from public.subscription_refund_requests where id=p_request_id;\n if not found then raise exception ''subscription refund request missing'' using errcode=''22023''; end if;\n select * into s from public.organization_subscriptions where organization_id=r.organization_id for update;\n select * into a from public.subscription_refund_applications where request_id=r.id;\n if found then return to_jsonb(a); end if;\n perform 1 from public.billing_sandbox_orders where id=r.order_id for update;\n select x.* into f from public.billing_sandbox_refunds x join public.subscription_refund_reservations l on l.refund_id=x.id where l.request_id=r.id for update of x;\n if f.id is null or f.state<>''succeeded'' or f.provider_refund_id is null or f.first_sent_at is null\n  or f.order_id<>r.order_id or f.amount_minor<>r.amount_minor\n  or f.payment_id::text is distinct from r.snapshot->>''payment_id'' then\n  raise exception ''subscription refund not confirmed'' using errcode=''55000''; end if;\n select * into b from public.subscription_refund_period_bindings where request_id=r.id;\n -- Only the exact materialized period may be terminated. Other rights require review.\n if b.request_id is null or b.kind not in (''confirmed'',''after_trial'') or s.trial_access_id is not null\n  or s.status not in (''active'',''expired'') or s.plan_version_id is distinct from b.plan_version_id\n  or s.period_start is distinct from b.period_start or s.period_end is distinct from b.period_end\n  or s.scheduled_plan_version_id is not null\n  or exists(select 1 from public.billing_recurring_orders ro\n   join public.billing_recurring_dispatches d on d.order_id=ro.id\n   where ro.organization_id=r.organization_id\n   and not exists(select 1 from public.billing_period_confirmations c where c.confirmation_id=ro.id)\n   and not exists(select 1 from public.billing_recurring_results p where p.order_id=ro.id and p.status=''canceled'' and not p.requires_review))\n  or exists(select 1 from platform_private.active_trial_paid_periods where organization_id=r.organization_id and order_id<>b.period_order_id and period_end>clock_timestamp()) then\n  raise exception ''subscription refund access review required'' using errcode=''55000''; end if;\n free_id:=platform_private.current_tariff_version(''free'',clock_timestamp());\n if free_id is null then raise exception ''current free tariff unavailable'' using errcode=''55000''; end if;\n previous:=to_jsonb(s);\n update public.organization_subscriptions set status=''free'',plan_version_id=free_id,\n period_start=null,period_end=null,cancel_at_period_end=false,scheduled_plan_version_id=null,scheduled_effective_at=null\n where organization_id=r.organization_id returning * into s;\n insert into public.subscription_refund_applications(request_id,refund_id,period_order_id,before_state,after_state)\n values(r.id,f.id,b.period_order_id,previous,to_jsonb(s)) returning * into a;\n return to_jsonb(a);\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.apply_future_trial_subscription_refund(uuid)","definition":"CREATE OR REPLACE FUNCTION platform_private.apply_future_trial_subscription_refund(p_request_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare r public.subscription_refund_requests%rowtype; b public.subscription_refund_period_bindings%rowtype;\n f public.billing_sandbox_refunds%rowtype; s public.organization_subscriptions%rowtype;\n paid public.billing_trial_paid_periods%rowtype; a public.subscription_refund_applications%rowtype;\nbegin\n perform platform_private.require_sandbox_environment();\n select * into r from public.subscription_refund_requests where id=p_request_id;\n if not found then raise exception ''subscription refund request missing'' using errcode=''22023''; end if;\n select * into s from public.organization_subscriptions where organization_id=r.organization_id for update;\n select * into a from public.subscription_refund_applications where request_id=r.id;\n if found then return to_jsonb(a); end if;\n perform 1 from public.billing_sandbox_orders where id=r.order_id for update;\n select x.* into f from public.billing_sandbox_refunds x join public.subscription_refund_reservations l on l.refund_id=x.id where l.request_id=r.id for update of x;\n if f.id is null or f.state<>''succeeded'' or f.provider_refund_id is null or f.first_sent_at is null\n or f.order_id<>r.order_id or f.amount_minor<>r.amount_minor\n or f.payment_id::text is distinct from r.snapshot->>''payment_id'' then\n raise exception ''subscription refund not confirmed'' using errcode=''55000''; end if;\n select * into b from public.subscription_refund_period_bindings where request_id=r.id;\n select * into paid from public.billing_trial_paid_periods where order_id=b.period_order_id;\n if b.kind is distinct from ''after_trial'' or paid.order_id is null\n or paid.organization_id is distinct from r.organization_id or paid.access_id is distinct from s.trial_access_id\n or paid.period_start is distinct from b.period_start or paid.period_end is distinct from b.period_end\n or paid.plan_version_id is distinct from b.plan_version_id or clock_timestamp()>=paid.period_start\n or s.status<>''trial'' then\n raise exception ''subscription refund access review required'' using errcode=''55000''; end if;\n insert into public.subscription_refund_applications(request_id,refund_id,period_order_id,before_state,after_state)\n values(r.id,f.id,b.period_order_id,to_jsonb(s),to_jsonb(s)) returning * into a;\n return to_jsonb(a);\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.apply_recurring_period(uuid)","definition":"CREATE OR REPLACE FUNCTION platform_private.apply_recurring_period(p_order_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare r public.billing_recurring_orders%rowtype; p public.billing_recurring_results%rowtype; checked jsonb; result jsonb;\nbegin\n perform platform_private.require_sandbox_environment();\n if current_setting(''transaction_isolation'')<>''read committed'' then raise exception ''recurring requires read committed'' using errcode=''40001''; end if;\n select * into r from public.billing_recurring_orders where id=p_order_id;\n if not found then raise exception ''recurring order unavailable'' using errcode=''22023''; end if;\n perform pg_advisory_xact_lock(hashtextextended(r.source_order_id::text,7350));\n perform pg_advisory_xact_lock(hashtextextended(r.id::text,7350));\n perform 1 from public.organization_subscriptions where organization_id=r.organization_id for update;\n if not exists(select 1 from public.billing_period_confirmations confirmed where confirmed.confirmation_id=r.id)\n and exists(select 1 from public.subscription_refund_requests rq\n join public.subscription_refund_reservations l on l.request_id=rq.id\n join public.billing_sandbox_refunds f on f.id=l.refund_id\n where rq.organization_id=r.organization_id and f.state not in (''canceled'',''rejected'')\n and not exists(select 1 from public.subscription_refund_applications applied_refund where applied_refund.request_id=rq.id)) then\n return jsonb_build_object(''state'',''requires_review'',''reason'',''subscription_refund_pending''); end if;\n select * into p from public.billing_recurring_results where order_id=r.id;\n if p.requires_review then return jsonb_build_object(''state'',''requires_review''); end if;\n if exists(select 1 from public.billing_period_confirmations where confirmation_id=r.id) then return jsonb_build_object(''state'',''applied''); end if;\n if exists(select 1 from public.billing_recurring_cancellations where order_id=r.id)\n or not exists(select 1 from public.billing_discount_reservations where order_id=r.id and state=''reserved'') then return jsonb_build_object(''state'',''unavailable''); end if;\n if (r.quote->>''requires_payment'')::boolean then\n  if p.status is distinct from ''succeeded'' or p.paid is distinct from true\n  or not exists(select 1 from public.billing_recurring_dispatches where order_id=r.id) then return jsonb_build_object(''state'',''payment_required''); end if;\n else\n  if (r.quote->>''amount_minor'')::bigint is distinct from 0 or exists(select 1 from public.billing_recurring_attempts where order_id=r.id) then return jsonb_build_object(''state'',''requires_review''); end if;\n  checked:=platform_private.review_recurring_order(r.id);\n  if checked->>''state''<>''ready'' then return checked; end if;\n end if;\n if clock_timestamp()<r.period_start then return jsonb_build_object(''state'',''deferred''); end if;\n if clock_timestamp()>=r.period_end then return jsonb_build_object(''state'',''requires_review''); end if;\n -- Ошибка конфликта ревизии откатывает выдачу и расход скидки вместе.\n result:=public.confirm_organization_subscription_period(r.organization_id,r.id,r.expected_revision,r.plan_version_id,r.period_start,r.period_end);\n perform platform_private.settle_discount_period(r.id,true);\n return jsonb_build_object(''state'',''applied'',''revision'',result->''revision'');\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.apply_subscription_refund(uuid)","definition":"CREATE OR REPLACE FUNCTION platform_private.apply_subscription_refund(p_request_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare r public.subscription_refund_requests%rowtype; b public.subscription_refund_period_bindings%rowtype;\n s public.organization_subscriptions%rowtype; a public.subscription_refund_applications%rowtype;\nbegin\n perform platform_private.require_sandbox_environment();\n if current_setting(''transaction_isolation'')<>''read committed'' then\n raise exception ''subscription refund requires read committed'' using errcode=''40001''; end if;\n select * into r from public.subscription_refund_requests where id=p_request_id;\n if not found then raise exception ''subscription refund request missing'' using errcode=''22023''; end if;\n select * into s from public.organization_subscriptions where organization_id=r.organization_id for update;\n select * into a from public.subscription_refund_applications where request_id=r.id;\n if found then return to_jsonb(a); end if;\n select * into b from public.subscription_refund_period_bindings where request_id=r.id;\n if b.request_id is null then raise exception ''subscription refund access review required'' using errcode=''55000''; end if;\n if b.kind=''after_trial'' then\n  if clock_timestamp()<b.period_start then\n   return platform_private.apply_future_trial_subscription_refund(r.id);\n  end if;\n  if s.trial_access_id is not null then\n   if not exists(select 1 from platform_private.active_trial_paid_periods p\n    where p.order_id=b.period_order_id and p.organization_id=r.organization_id\n    and p.access_id=s.trial_access_id and p.plan_version_id=b.plan_version_id\n    and p.period_start=b.period_start and p.period_end=b.period_end) then\n    raise exception ''subscription refund access review required'' using errcode=''55000''; end if;\n   perform public.advance_organization_trial(r.organization_id);\n  end if;\n end if;\n return platform_private.apply_current_subscription_refund(r.id);\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.authorize_recurring_send(uuid,uuid)","definition":"CREATE OR REPLACE FUNCTION platform_private.authorize_recurring_send(p_order_id uuid, p_key uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare r public.billing_recurring_orders%rowtype; s public.organization_subscriptions%rowtype; a public.billing_recurring_attempts%rowtype;\nbegin\n perform platform_private.require_sandbox_environment();\n if current_setting(''transaction_isolation'')<>''read committed'' then raise exception ''recurring requires read committed'' using errcode=''40001''; end if;\n select * into r from public.billing_recurring_orders where id=p_order_id;\n if not found then return false; end if;\n perform pg_advisory_xact_lock(hashtextextended(r.source_order_id::text,7350));\n select * into s from public.organization_subscriptions where organization_id=r.organization_id for update;\n if exists(select 1 from public.subscription_refund_requests rq\n join public.subscription_refund_reservations l on l.request_id=rq.id\n join public.billing_sandbox_refunds f on f.id=l.refund_id\n where rq.organization_id=r.organization_id and f.state not in (''canceled'',''rejected'')\n and not exists(select 1 from public.subscription_refund_applications applied_refund where applied_refund.request_id=rq.id)) then return false; end if;\n select * into a from public.billing_recurring_attempts where order_id=r.id;\n return coalesce(a.idempotency_key=p_key and clock_timestamp()>=a.created_at and clock_timestamp()<a.created_at+interval ''23 hours''\n and platform_private.recurring_source_revision(s)=r.expected_revision and s.plan_version_id=r.plan_version_id and s.period_end=r.period_start and not s.cancel_at_period_end\n and not exists(select 1 from public.billing_recurring_revocations where consent_id=r.consent_id)\n and exists(select 1 from public.billing_sandbox_application_scope where organization_id=r.organization_id)\n and exists(select 1 from public.billing_discount_reservations where order_id=r.id and state=''reserved'')\n and not exists(select 1 from public.billing_recurring_results where order_id=r.id)\n and platform_private.tariff_allows_renewal(r.plan_version_id,clock_timestamp(),true)\n and platform_private.tariff_allows_renewal(r.plan_version_id,r.period_start,true),false);\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.begin_recurring_attempt(uuid)","definition":"CREATE OR REPLACE FUNCTION platform_private.begin_recurring_attempt(p_order_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare r public.billing_recurring_orders%rowtype; checked jsonb; attempt public.billing_recurring_attempts%rowtype;\nbegin\n perform platform_private.require_sandbox_environment();\n if current_setting(''transaction_isolation'')<>''read committed'' then raise exception ''recurring requires read committed'' using errcode=''40001''; end if;\n select * into r from public.billing_recurring_orders where id=p_order_id;\n if not found then raise exception ''recurring order unavailable'' using errcode=''22023''; end if;\n perform pg_advisory_xact_lock(hashtextextended(r.source_order_id::text,7350));\n perform 1 from public.organization_subscriptions where organization_id=r.organization_id for update;\n if platform_private.close_recurring_attempt(r.id) then return jsonb_build_object(''state'',''cancelled''); end if; select * into attempt from public.billing_recurring_attempts where order_id=r.id;\n if found then return jsonb_build_object(''state'',''reconciliation_required'',''idempotency_key'',attempt.idempotency_key); end if;\n checked:=platform_private.review_recurring_order(r.id);\n if checked->>''state''<>''ready'' then return checked; end if;\n if (checked->>''requires_payment'')::boolean is distinct from true then return jsonb_build_object(''state'',''zero_amount''); end if;\n insert into public.billing_recurring_attempts(order_id,provider_method_id,shop_id,amount_minor,currency)\n select r.id,m.provider_method_id,o.shop_id,(r.quote->>''amount_minor'')::bigint,''RUB''\n from public.billing_recurring_methods m join public.billing_sandbox_orders o on o.id=r.source_order_id\n where m.consent_id=r.consent_id returning * into attempt;\n if not found then raise exception ''recurring method unavailable'' using errcode=''55000''; end if;\n return jsonb_build_object(''state'',''prepared'',''idempotency_key'',attempt.idempotency_key);\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.check_initial_billing_environment()","definition":"CREATE OR REPLACE FUNCTION platform_private.check_initial_billing_environment()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare relation_name text; populated boolean;\nbegin\n if new.environment<>''production'' then return new; end if;\n -- Explicit conservative inventory: reject operational history, not catalog or\n -- organization rows. Lock each source against concurrent provisioning.\n for relation_name in\n  select c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace\n  where n.nspname=''public'' and c.relkind=''r'' and (\n   c.relname like ''billing_sandbox_%'' or c.relname like ''billing_recurring_%''\n   or c.relname in (''billing_discount_checkouts'',''billing_trial_paid_periods'',\n    ''billing_fiscal_acceptance_fixtures'',''billing_receipt_snapshots'',\n    ''billing_subscription_fiscal_operations'',''billing_period_confirmations'',\n    ''billing_confirmation_inbox'',''billing_review_resolutions''))\n  order by c.relname\n loop\n  execute format(''lock table public.%I in share mode'',relation_name);\n  execute format(''select exists(select 1 from public.%I)'',relation_name) into populated;\n  if populated then raise exception ''production environment requires clean billing history: %'',relation_name using errcode=''55000''; end if;\n end loop;\n lock table public.billing_fiscal_policies in share mode;\n if exists(select 1 from public.billing_fiscal_policies where environment=''sandbox'') then\n  raise exception ''production environment requires clean fiscal policies'' using errcode=''55000'';\n end if;\n return new;\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.check_linked_fiscal_refund_send(uuid,jsonb)","definition":"CREATE OR REPLACE FUNCTION platform_private.check_linked_fiscal_refund_send(p_command_id uuid, p_expected jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare r public.subscription_refund_requests%rowtype; x public.billing_subscription_fiscal_operations%rowtype;\n s public.billing_subscription_fiscal_operation_status%rowtype; f public.billing_sandbox_refunds%rowtype;\nbegin\n perform platform_private.require_sandbox_environment();\n select * into r from public.subscription_refund_requests where id=p_command_id;\n if not found then raise exception ''fiscal send denied'' using errcode=''55000''; end if;\n perform 1 from public.organization_subscriptions where organization_id=r.organization_id for update;\n perform 1 from public.billing_sandbox_orders where id=r.order_id for update;\n select * into x from public.billing_subscription_fiscal_operations where command_id=p_command_id;\n select * into s from public.billing_subscription_fiscal_operation_status where command_id=p_command_id;\n select * into f from public.billing_sandbox_refunds where fiscal_command_id=p_command_id;\n if x.command_id is null or s.command_id is null or f.id is null\n  or s.state<>''unknown'' or s.first_sent_at is null or s.first_sent_at<=clock_timestamp()-interval ''23 hours''\n  or s.provider_refund_id is not null or s.provider_receipt_id is not null or s.requires_review\n  or f.state<>''sending'' or f.provider_refund_id is not null or f.first_sent_at is distinct from s.first_sent_at\n  or p_expected->>''key'' is distinct from x.idempotency_key::text\n  or p_expected->>''sha256'' is distinct from x.body_sha256\n  or (p_expected->>''firstSentAt'')::timestamptz is distinct from s.first_sent_at\n  or exists(select 1 from public.billing_subscription_fiscal_operations q\n   join public.billing_subscription_fiscal_operation_status t using(command_id) where q.order_id=r.order_id and t.requires_review)\n  or not exists(select 1 from public.billing_sandbox_payment_results p where p.order_id=r.order_id\n   and p.payment_id=f.payment_id and p.status=''succeeded'' and p.paid and not p.requires_review) then\n  raise exception ''fiscal send denied'' using errcode=''55000''; end if;\n perform platform_private.check_subscription_refund_access(r.id);\n return jsonb_build_object(''authorized'',true,''commandId'',p_command_id,''key'',x.idempotency_key,''sha256'',x.body_sha256);\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.claim_recurring_dispatch(uuid,uuid)","definition":"CREATE OR REPLACE FUNCTION platform_private.claim_recurring_dispatch(p_order_id uuid, p_key uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare r public.billing_recurring_orders%rowtype;\nbegin\n perform platform_private.require_sandbox_environment();\n if current_setting(''transaction_isolation'')<>''read committed'' then raise exception ''recurring requires read committed'' using errcode=''40001''; end if;\n select * into r from public.billing_recurring_orders where id=p_order_id;\n if not found then return false; end if;\n perform pg_advisory_xact_lock(hashtextextended(r.source_order_id::text,7350));\n if exists(select 1 from public.billing_recurring_dispatches where order_id=r.id) then return false; end if;\n if platform_private.authorize_recurring_send(r.id,p_key) is distinct from true then return false; end if;\n insert into public.billing_recurring_dispatches(order_id) values(r.id);\n return true;\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.claim_subscription_fiscal_operation(uuid)","definition":"CREATE OR REPLACE FUNCTION platform_private.claim_subscription_fiscal_operation(p_command_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare x public.billing_subscription_fiscal_operations%rowtype;\n s public.billing_subscription_fiscal_operation_status%rowtype; o public.billing_sandbox_orders%rowtype;\n action text; payment uuid;\nbegin\n perform platform_private.require_sandbox_environment();\n select * into x from public.billing_subscription_fiscal_operations where command_id=p_command_id;\n if not found then raise exception ''fiscal operation unavailable'' using errcode=''55000''; end if;\n select * into o from public.billing_sandbox_orders where id=x.order_id for update;\n select * into s from public.billing_subscription_fiscal_operation_status where command_id=x.command_id for update;\n if not found then raise exception ''fiscal operation unavailable'' using errcode=''55000''; end if;\n if exists(select 1 from public.billing_subscription_fiscal_operations q\n  join public.billing_subscription_fiscal_operation_status t using(command_id)\n  where q.order_id=x.order_id and t.requires_review) then return jsonb_build_object(''action'',''review''); end if;\n select payment_id into payment from public.billing_subscription_fiscal_ledgers where order_id=x.order_id;\n if not exists(select 1 from public.billing_sandbox_payment_results p where p.order_id=o.id\n  and p.payment_id=payment and p.shop_id=o.shop_id and p.status=''succeeded'' and p.paid and not p.requires_review) then\n  raise exception ''fiscal payment unverified'' using errcode=''55000''; end if;\n if s.first_sent_at is null then\n  if s.state<>''reserved'' then raise exception ''fiscal claim invalid'' using errcode=''55000''; end if;\n  update public.billing_subscription_fiscal_operation_status set state=''unknown'',first_sent_at=clock_timestamp()\n   where command_id=x.command_id returning * into s;\n  action:=''send'';\n else\n  action:=''reconcile'';\n  if s.provider_refund_id is null and s.provider_receipt_id is null\n   and s.first_sent_at<=clock_timestamp()-interval ''23 hours'' then\n   update public.billing_subscription_fiscal_operation_status set requires_review=true where command_id=x.command_id;\n   return jsonb_build_object(''action'',''review'');\n  end if;\n end if;\n return jsonb_build_object(''action'',action,''commandId'',x.command_id,''orderId'',x.order_id,''paymentId'',payment,\n  ''shopId'',o.shop_id,''kind'',x.kind,''body'',x.body,''key'',x.idempotency_key,''sha256'',x.body_sha256,\n  ''amountMinor'',x.amount_minor,''expectedItems'',platform_private.subscription_fiscal_expected_items(x.command_id),\n  ''expectedRefundedMinor'',(select coalesce(sum(q.amount_minor),0) from public.billing_subscription_fiscal_operations q\n   join public.billing_subscription_fiscal_operation_status t using(command_id)\n   where q.order_id=x.order_id and q.expected_version<x.expected_version and q.kind<>''settlement'' and t.state=''succeeded''),\n  ''priorReceipts'',(select coalesce(jsonb_agg(jsonb_build_object(''id'',t.provider_receipt_id,\n   ''type'',case when q.kind=''settlement'' then ''payment'' else ''refund'' end,''refundId'',t.provider_refund_id,\n   ''items'',platform_private.subscription_fiscal_expected_items(q.command_id),\n   ''settlements'',case when q.kind=''settlement'' then q.body->''settlements'' else null end) order by q.expected_version),''[]''::jsonb)\n   from public.billing_subscription_fiscal_operations q join public.billing_subscription_fiscal_operation_status t using(command_id)\n   where q.order_id=x.order_id and q.expected_version<x.expected_version and t.state=''succeeded''),\n  ''firstSentAt'',s.first_sent_at,''state'',s.state,''refundId'',s.provider_refund_id,''receiptId'',s.provider_receipt_id);\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.claim_subscription_refund_dispatch(uuid)","definition":"CREATE OR REPLACE FUNCTION platform_private.claim_subscription_refund_dispatch(p_refund_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare request public.subscription_refund_requests%rowtype; refund public.billing_sandbox_refunds%rowtype;\n payment public.billing_sandbox_payment_results%rowtype; order_row public.billing_sandbox_orders%rowtype;\n authorized timestamptz; used bigint;\nbegin\n perform platform_private.require_sandbox_environment();\n perform public.require_platform_owner();\n select r.* into request from public.subscription_refund_requests r join public.subscription_refund_reservations l on l.request_id=r.id where l.refund_id=p_refund_id;\n if not found then raise exception ''subscription refund request missing'' using errcode=''22023''; end if;\n perform 1 from public.organization_subscriptions where organization_id=request.organization_id for update;\n select * into order_row from public.billing_sandbox_orders where id=request.order_id for update;\n select * into refund from public.billing_sandbox_refunds where id=p_refund_id for update;\n if exists(select 1 from public.subscription_refund_dispatches where refund_id=refund.id)\n or refund.state<>''reserved'' or refund.first_sent_at is not null or refund.provider_refund_id is not null then\n return jsonb_build_object(''can_send'',false,''refund_id'',refund.id); end if;\n if not exists(select 1 from public.billing_sandbox_application_scope where organization_id=request.organization_id) then\n raise exception ''sandbox refund scope denied'' using errcode=''42501''; end if;\n perform platform_private.check_subscription_refund_access(request.id);\n select * into payment from public.billing_sandbox_payment_results where order_id=order_row.id;\n if payment.order_id is null or payment.status<>''succeeded'' or not payment.paid or payment.requires_review\n or payment.payment_id is distinct from refund.payment_id or payment.payment_id::text is distinct from request.snapshot->>''payment_id''\n or refund.order_id<>request.order_id or refund.amount_minor<>request.amount_minor\n or order_row.organization_id<>request.organization_id or order_row.currency<>''RUB''\n or order_row.amount_minor is distinct from (request.snapshot->>''paid_minor'')::bigint\n or order_row.period_start is distinct from (request.snapshot->>''period_start'')::timestamptz\n or order_row.period_end is distinct from (request.snapshot->>''period_end'')::timestamptz then\n raise exception ''subscription refund snapshot changed'' using errcode=''55000''; end if;\n select coalesce(sum(amount_minor),0) into used from public.billing_sandbox_refunds where order_id=order_row.id and state not in (''canceled'',''rejected'');\n if used>order_row.amount_minor or refund.amount_minor<=0 then raise exception ''invalid refund amount'' using errcode=''22023''; end if;\n insert into public.subscription_refund_dispatches(refund_id,actor_id,request_snapshot) values(refund.id,auth.uid(),jsonb_build_object(''refund_id'',refund.id,''idempotency_key'',refund.id,''payment_id'',refund.payment_id,''amount_minor'',refund.amount_minor,''currency'',order_row.currency,''shop_id'',order_row.shop_id)) returning authorized_at into authorized;\n update public.billing_sandbox_refunds set state=''sending'',first_sent_at=authorized,updated_at=authorized where id=refund.id;\n return jsonb_build_object(''can_send'',true,''refund_id'',refund.id,''idempotency_key'',refund.id,\n ''payment_id'',refund.payment_id,''amount_minor'',refund.amount_minor,''currency'',order_row.currency,''shop_id'',order_row.shop_id);\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.confirm_trial_checkout_replacement(uuid)","definition":"CREATE OR REPLACE FUNCTION platform_private.confirm_trial_checkout_replacement(p_order_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare c public.billing_discount_checkouts%rowtype; o public.billing_sandbox_offers%rowtype;\n s public.organization_subscriptions%rowtype; g public.billing_trial_access%rowtype;\n terms jsonb; previous jsonb; result jsonb; started timestamptz; ending timestamptz;\nbegin\n perform platform_private.require_sandbox_environment();\n perform pg_advisory_xact_lock(hashtextextended(p_order_id::text,7350));\n select * into c from public.billing_discount_checkouts where id=p_order_id;\n if not found or ((c.quote->>''amount_minor'')::bigint is distinct from 0 and not platform_private.has_verified_discount_payment(p_order_id)) then raise exception ''zero trial checkout required'' using errcode=''55000''; end if;\n select * into o from public.billing_sandbox_offers where id=c.offer_id;\n select * into s from public.organization_subscriptions where organization_id=c.organization_id for update;\n terms:=c.quote->''trial_purchase'';\n if terms->>''transition'' is distinct from ''replace_trial_on_payment'' then raise exception ''trial replacement required'' using errcode=''55000''; end if;\n if s.revision is distinct from o.expected_revision or s.revision is distinct from (terms->>''subscription_revision'')::bigint then\n raise exception ''billing revision conflict'' using errcode=''40001''; end if;\n select * into g from public.billing_trial_access where id=s.trial_access_id for update;\n started:=clock_timestamp();\n if g.id is null or g.id is distinct from (terms->>''access_id'')::uuid\n or g.generation is distinct from (terms->>''generation'')::integer\n or g.state not in (''scheduled'',''active'') or g.access_kind<>''trial''\n or not public.trial_access_matches(s,g) or started<g.starts_at or started>=g.ends_at\n or g.ends_at is distinct from (terms->>''trial_ends_at'')::timestamptz then\n raise exception ''trial checkout context changed'' using errcode=''40001''; end if;\n if o.period_months is null or o.valid_until<=started\n or o.plan_version_id is distinct from (terms->>''target_plan_version_id'')::uuid\n or (select plan_key from public.billing_plan_versions where id=o.plan_version_id)\n is not distinct from (select plan_key from public.billing_plan_versions where id=g.plan_version_id) then\n raise exception ''invalid trial replacement target'' using errcode=''22023''; end if;\n ending:=((started at time zone ''Europe/Moscow'')+make_interval(months=>o.period_months)) at time zone ''Europe/Moscow'';\n previous:=to_jsonb(s);\n update public.organization_subscriptions set status=''active'',plan_version_id=o.plan_version_id,\n period_start=started,period_end=ending,trial_access_id=null where organization_id=c.organization_id returning * into s;\n update public.billing_trial_access set state=''finished'',was_started=true where id=g.id;\n insert into public.billing_trial_transitions(access_id,kind,generation,before_state,after_state)\n values(g.id,''finished'',g.generation,previous,to_jsonb(s));\n result:=jsonb_build_object(''organization_id'',s.organization_id,''revision'',s.revision,''confirmation_id'',p_order_id,\n ''period_start'',started,''period_end'',ending,''trial_remaining_preserved'',false);\n insert into public.billing_period_confirmations(confirmation_id,organization_id,request,before_state,result)\n values(p_order_id,c.organization_id,jsonb_build_object(''organization_id'',c.organization_id,''revision'',o.expected_revision,\n ''plan'',o.plan_version_id,''start'',started,''end'',ending,''source'',''zero_trial_replacement''),previous,result);\n return result;\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.defer_future_discount_payment(uuid)","definition":"CREATE OR REPLACE FUNCTION platform_private.defer_future_discount_payment(p_order_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare o public.billing_sandbox_orders%rowtype; s public.organization_subscriptions%rowtype; c public.billing_discount_checkouts%rowtype;\nbegin\n perform platform_private.require_sandbox_environment();\n perform pg_advisory_xact_lock(hashtextextended(p_order_id::text,7350));\n select * into c from public.billing_discount_checkouts where id=p_order_id;\n if not found or c.quote ? ''trial_purchase'' then return false; end if;\n select * into s from public.organization_subscriptions where organization_id=c.organization_id for update;\n select * into o from public.billing_sandbox_orders where id=p_order_id for update;\n if not found or clock_timestamp()>=o.period_start\n or exists(select 1 from public.billing_discount_fulfillments where order_id=p_order_id) then return false; end if;\n if not platform_private.has_verified_discount_payment(p_order_id) then raise exception ''discount payment unverified'' using errcode=''55000''; end if;\n if s.revision is distinct from o.expected_revision or s.status<>''active'' or s.trial_access_id is not null\n or s.period_end is distinct from o.period_start or o.period_end<=o.period_start then\n raise exception ''future discount subscription conflict'' using errcode=''40001''; end if;\n perform platform_private.begin_discount_checkout_execution(p_order_id);\n -- Очередь sandbox сверяет сохранённый платёж, не создавая новую оплату.\n insert into public.billing_sandbox_reconciliation_jobs(order_id) values(p_order_id) on conflict do nothing;\n return true;\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.fulfill_discount_payment(uuid)","definition":"CREATE OR REPLACE FUNCTION platform_private.fulfill_discount_payment(p_order_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare c public.billing_discount_checkouts%rowtype; o public.billing_sandbox_orders%rowtype;\n payment public.billing_sandbox_payment_results%rowtype; s public.organization_subscriptions%rowtype; result jsonb;\nbegin\n perform platform_private.require_sandbox_environment();\n if exists(select 1 from public.subscription_refund_applications where period_order_id=p_order_id) then\n raise exception ''subscription period refunded'' using errcode=''55000''; end if;\n if current_setting(''transaction_isolation'')<>''read committed'' then raise exception ''discount requires read committed'' using errcode=''40001''; end if;\n perform pg_advisory_xact_lock(hashtextextended(p_order_id::text,7350));\n select * into c from public.billing_discount_checkouts where id=p_order_id;\n if not found then raise exception ''discount checkout unavailable'' using errcode=''22023''; end if;\n select * into s from public.organization_subscriptions where organization_id=c.organization_id for update;\n select b.* into o from public.billing_sandbox_orders b join public.billing_discount_payment_links l on l.payment_order_id=b.id where l.checkout_id=c.id for update of b;\n select * into payment from public.billing_sandbox_payment_results where order_id=o.id;\n if o.id is null or o.organization_id<>c.organization_id or o.amount_minor is distinct from (c.quote->>''amount_minor'')::bigint\n or o.amount_minor<=0 or o.currency<>''RUB'' or o.first_sent_at is null\n or payment.order_id is null or payment.shop_id<>o.shop_id or payment.status<>''succeeded'' or not payment.paid or payment.requires_review\n or not exists(select 1 from public.billing_sandbox_application_scope where organization_id=c.organization_id) then\n raise exception ''discount payment unverified'' using errcode=''55000''; end if;\n select f.result into result from public.billing_discount_fulfillments f where order_id=c.id;\n if found then return result; end if;\n if (s.trial_access_id is not null or s.status=''trial'') and coalesce(c.quote#>>''{trial_purchase,transition}'','''') not in (''after_trial'',''replace_trial_on_payment'') then\n raise exception ''paid trial fulfillment pending'' using errcode=''55000''; end if;\n perform platform_private.begin_discount_checkout_execution(c.id);\n if c.quote#>>''{trial_purchase,transition}''=''after_trial'' then\n result:=platform_private.schedule_confirmed_period_after_trial(c.id);\n elsif c.quote#>>''{trial_purchase,transition}''=''replace_trial_on_payment'' then\n result:=platform_private.confirm_trial_checkout_replacement(c.id);\n else result:=public.confirm_organization_subscription_period(c.organization_id,c.id,o.expected_revision,o.plan_version_id,o.period_start,o.period_end); end if;\n perform platform_private.settle_discount_period(c.id,true);\n result:=result||jsonb_build_object(''order_id'',c.id,''status'',''completed'',''amount_minor'',o.amount_minor,''payment_required'',true);\n insert into public.billing_discount_fulfillments(order_id,result) values(c.id,result);\n update public.billing_discount_checkout_states set state=''completed'',changed_at=clock_timestamp() where order_id=c.id;\n update public.billing_sandbox_orders set state=''finished'' where id=o.id;\n return result;\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.fulfill_zero_discount_checkout(uuid)","definition":"CREATE OR REPLACE FUNCTION platform_private.fulfill_zero_discount_checkout(p_order_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare checkout public.billing_discount_checkouts%rowtype; offer public.billing_sandbox_offers%rowtype;\n subscription public.organization_subscriptions%rowtype; result jsonb;\nbegin\n perform platform_private.require_sandbox_environment();\n if exists(select 1 from public.subscription_refund_applications where period_order_id=p_order_id) then\n raise exception ''subscription period refunded'' using errcode=''55000''; end if;\n if current_setting(''transaction_isolation'')<>''read committed'' then raise exception ''discount requires read committed'' using errcode=''40001''; end if;\n if p_order_id is null then raise exception ''invalid discount checkout'' using errcode=''22023''; end if;\n -- Такой же порядок, как у существующего подтверждения периода.\n perform pg_advisory_xact_lock(hashtextextended(p_order_id::text,7350));\n select * into checkout from public.billing_discount_checkouts where id=p_order_id;\n if not found then raise exception ''discount checkout unavailable'' using errcode=''22023''; end if;\n select * into subscription from public.organization_subscriptions where organization_id=checkout.organization_id for update;\n select f.result into result from public.billing_discount_fulfillments f where order_id=p_order_id;\n if found then return result; end if;\n if (checkout.quote->>''amount_minor'')::bigint is distinct from 0\n or (checkout.quote->>''requires_payment'')::boolean is distinct from false then\n raise exception ''discount checkout requires verified payment'' using errcode=''55000''; end if;\n select * into offer from public.billing_sandbox_offers where id=checkout.offer_id;\n if offer.valid_until<=clock_timestamp() then raise exception ''sandbox offer expired'' using errcode=''22023''; end if;\n -- До отдельной реализации не сокращать trial и не обходить будущую границу периода.\n if (subscription.trial_access_id is not null or subscription.status=''trial'') and coalesce(checkout.quote#>>''{trial_purchase,transition}'','''') not in (''replace_trial_on_payment'',''after_trial'') then\n raise exception ''trial purchase requires scheduled fulfillment'' using errcode=''55000''; end if;\n perform platform_private.begin_discount_checkout_execution(p_order_id);\n if checkout.quote#>>''{trial_purchase,transition}''=''replace_trial_on_payment'' then\n result:=platform_private.confirm_trial_checkout_replacement(p_order_id); elsif checkout.quote#>>''{trial_purchase,transition}''=''after_trial'' then result:=platform_private.schedule_confirmed_period_after_trial(p_order_id);\n else result:=public.confirm_organization_subscription_period(checkout.organization_id,p_order_id,offer.expected_revision,\n offer.plan_version_id,offer.period_start,offer.period_end); end if;\n perform platform_private.settle_discount_period(p_order_id,true);\n result:=result||jsonb_build_object(''order_id'',p_order_id,''status'',''completed'',''amount_minor'',0,''payment_required'',false);\n insert into public.billing_discount_fulfillments(order_id,result) values(p_order_id,result);\n update public.billing_discount_checkout_states set state=''completed'',changed_at=clock_timestamp() where order_id=p_order_id;\n return result;\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.guard_sandbox_period_confirmation()","definition":"CREATE OR REPLACE FUNCTION platform_private.guard_sandbox_period_confirmation()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nbegin\n if exists(select 1 from public.billing_sandbox_orders where id=new.confirmation_id) then\n  perform platform_private.require_sandbox_environment();\n end if;\n return new;\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.prepare_subscription_refund_recovery(uuid)","definition":"CREATE OR REPLACE FUNCTION platform_private.prepare_subscription_refund_recovery(p_refund_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare request public.subscription_refund_requests%rowtype; refund public.billing_sandbox_refunds%rowtype;\n order_row public.billing_sandbox_orders%rowtype; authorized timestamptz; payload jsonb;\nbegin\n perform public.require_platform_owner();\n if not exists(select 1 from public.billing_sandbox_refunds where id=p_refund_id and provider_refund_id is not null) then\n  perform platform_private.require_sandbox_environment();\n end if;\n select r.* into request from public.subscription_refund_requests r join public.subscription_refund_reservations l on l.request_id=r.id where l.refund_id=p_refund_id;\n if not found then raise exception ''subscription refund request missing'' using errcode=''22023''; end if;\n perform 1 from public.organization_subscriptions where organization_id=request.organization_id for update;\n select * into order_row from public.billing_sandbox_orders where id=request.order_id for update;\n select * into refund from public.billing_sandbox_refunds where id=p_refund_id for update;\n select authorized_at,request_snapshot into authorized,payload from public.subscription_refund_dispatches where refund_id=refund.id;\n if authorized is null or authorized is distinct from refund.first_sent_at\n or refund.order_id<>request.order_id or refund.amount_minor<>request.amount_minor\n or refund.payment_id::text is distinct from request.snapshot->>''payment_id''\n or order_row.organization_id<>request.organization_id or order_row.currency<>''RUB''\n or not exists(select 1 from public.billing_sandbox_application_scope where organization_id=request.organization_id) then\n raise exception ''subscription refund recovery unavailable'' using errcode=''55000''; end if;\n if payload is distinct from jsonb_build_object(''refund_id'',refund.id,''idempotency_key'',refund.id,''payment_id'',refund.payment_id,''amount_minor'',refund.amount_minor,''currency'',order_row.currency,''shop_id'',order_row.shop_id) then return jsonb_build_object(''action'',''manual_review''); end if;\n if refund.state=''review'' then return jsonb_build_object(''action'',''manual_review''); end if;\n if refund.provider_refund_id is not null then\n  return jsonb_build_object(''action'',''read_provider'',''refund_id'',refund.id,''provider_refund_id'',refund.provider_refund_id,''shop_id'',order_row.shop_id);\n end if;\n if refund.state<>''sending'' or clock_timestamp()<authorized or clock_timestamp()>=authorized+interval ''23 hours'' then\n  return jsonb_build_object(''action'',''manual_review''); end if;\n return jsonb_build_object(''action'',''retry_same_request'',''refund_id'',refund.id,''idempotency_key'',refund.id,\n ''payment_id'',refund.payment_id,''amount_minor'',refund.amount_minor,''currency'',order_row.currency,''shop_id'',order_row.shop_id,\n ''valid_until'',authorized+interval ''23 hours'');\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.protect_billing_environment_identity()","definition":"CREATE OR REPLACE FUNCTION platform_private.protect_billing_environment_identity()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\nbegin\n if tg_op=''UPDATE'' and new is not distinct from old then return new; end if;\n raise exception ''billing environment identity immutable'' using errcode=''55000'';\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.record_linked_subscription_fiscal_refund(uuid,jsonb)","definition":"CREATE OR REPLACE FUNCTION platform_private.record_linked_subscription_fiscal_refund(p_command_id uuid, p_result jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare r public.subscription_refund_requests%rowtype; f public.billing_sandbox_refunds%rowtype;\n s public.billing_subscription_fiscal_operation_status%rowtype; result_state text; money jsonb;\nbegin\n perform platform_private.require_sandbox_environment();\n if current_setting(''transaction_isolation'')<>''read committed'' then raise exception ''subscription refund requires read committed'' using errcode=''40001''; end if;\n select r0.* into r from public.subscription_refund_requests r0\n join public.subscription_refund_reservations l on l.request_id=r0.id\n join public.billing_sandbox_refunds f0 on f0.id=l.refund_id and f0.fiscal_command_id=r0.id\n where r0.id=p_command_id;\n if not found then raise exception ''linked fiscal refund unavailable'' using errcode=''55000''; end if;\n perform 1 from public.organization_subscriptions where organization_id=r.organization_id for update;\n perform 1 from public.billing_sandbox_orders where id=r.order_id for update;\n select * into f from public.billing_sandbox_refunds where fiscal_command_id=r.id for update;\n if p_result->>''commandId'' is distinct from p_command_id::text then\n  raise exception ''fiscal result invalid'' using errcode=''22023''; end if;\n result_state:=platform_private.record_subscription_fiscal_result(p_command_id,(p_result->>''paymentId'')::uuid,\n  p_result->>''shopId'',p_result->>''bodySha256'',(p_result->>''amountMinor'')::bigint,p_result->>''state'',\n  (p_result->>''refundId'')::uuid,p_result->>''receiptId'',p_result->>''receiptStatus'');\n select * into s from public.billing_subscription_fiscal_operation_status where command_id=p_command_id;\n -- Always use the persisted verified state, never a conflicting incoming status.\n if s.provider_refund_id is not null and s.state in (''pending'',''succeeded'',''canceled'') then\n  money:=platform_private.record_subscription_refund_result(f.id,p_result->>''shopId'',f.payment_id,\n   s.provider_refund_id,s.state,f.amount_minor,''RUB'');\n end if;\n return jsonb_build_object(''state'',result_state,''receiptStatus'',s.receipt_status,\n  ''accessState'',coalesce(money->>''access_state'',''not_applied''));\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.record_recurring_result(uuid,jsonb)","definition":"CREATE OR REPLACE FUNCTION platform_private.record_recurring_result(p_order_id uuid, p_payment jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare r public.billing_recurring_orders%rowtype; old public.billing_recurring_results%rowtype; payment uuid; status text; paid boolean;\nbegin\n perform platform_private.require_sandbox_environment();\n if current_setting(''transaction_isolation'')<>''read committed'' then raise exception ''recurring requires read committed'' using errcode=''40001''; end if;\n if p_payment->''test'' is distinct from ''true''::jsonb or jsonb_typeof(p_payment->''paid'') is distinct from ''boolean''\n or p_payment->>''status'' is null or p_payment->>''status'' not in (''pending'',''waiting_for_capture'',''succeeded'',''canceled'') then raise exception ''invalid recurring result'' using errcode=''22023''; end if;\n payment:=(p_payment->>''paymentId'')::uuid; status:=p_payment->>''status''; paid:=(p_payment->>''paid'')::boolean;\n if payment is null or paid<>(status=''succeeded'') then raise exception ''invalid recurring result'' using errcode=''22023''; end if;\n select * into r from public.billing_recurring_orders where id=p_order_id;\n if not found then raise exception ''recurring order unavailable'' using errcode=''22023''; end if;\n perform pg_advisory_xact_lock(hashtextextended(r.source_order_id::text,7350));\n perform 1 from public.organization_subscriptions where organization_id=r.organization_id for update;\n if not exists(select 1 from public.billing_recurring_attempts where order_id=r.id) then raise exception ''recurring attempt unavailable'' using errcode=''22023''; end if;\n select * into old from public.billing_recurring_results where order_id=r.id for update;\n if not found then\n insert into public.billing_recurring_results(order_id,payment_id,status,paid) values(r.id,payment,status,paid);\n elsif old.payment_id<>payment or (old.status in (''succeeded'',''canceled'') and status in (''succeeded'',''canceled'') and old.status<>status) then\n update public.billing_recurring_results set requires_review=true,checked_at=clock_timestamp() where order_id=r.id;\n elsif old.status not in (''succeeded'',''canceled'') and not (old.status=''waiting_for_capture'' and status=''pending'') then\n update public.billing_recurring_results set status=p_payment->>''status'',paid=(p_payment->>''paid'')::boolean,checked_at=clock_timestamp() where order_id=r.id;\n end if;\n select * into old from public.billing_recurring_results where order_id=r.id;\n perform platform_private.close_recurring_attempt(r.id); return jsonb_build_object(''paymentId'',old.payment_id,''status'',old.status,''paid'',old.paid,''requiresReview'',old.requires_review);\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.record_subscription_fiscal_result(uuid,uuid,text,text,bigint,text,uuid,text,text)","definition":"CREATE OR REPLACE FUNCTION platform_private.record_subscription_fiscal_result(p_command_id uuid, p_payment_id uuid, p_shop_id text, p_body_sha256 text, p_amount_minor bigint, p_state text, p_refund_id uuid, p_receipt_id text, p_receipt_status text)\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare x public.billing_subscription_fiscal_operations%rowtype;\n s public.billing_subscription_fiscal_operation_status%rowtype; shop text; payment uuid;\n next_receipt text; conflict boolean:=false;\nbegin\n perform platform_private.require_sandbox_environment();\n select * into x from public.billing_subscription_fiscal_operations where command_id=p_command_id;\n if not found then raise exception ''fiscal operation unavailable'' using errcode=''55000''; end if;\n select shop_id into shop from public.billing_sandbox_orders where id=x.order_id for update;\n select * into s from public.billing_subscription_fiscal_operation_status where command_id=x.command_id for update;\n if not found or s.first_sent_at is null then raise exception ''fiscal send not claimed'' using errcode=''55000''; end if;\n if s.requires_review then return ''review''; end if;\n select payment_id into payment from public.billing_subscription_fiscal_ledgers where order_id=x.order_id;\n if p_payment_id is distinct from payment or p_shop_id is distinct from shop\n  or p_body_sha256 is distinct from x.body_sha256 or p_amount_minor is distinct from x.amount_minor\n  or p_state is null or p_state not in (''pending'',''succeeded'',''canceled'')\n  or (p_receipt_id is not null and p_receipt_id !~ ''^r[at]-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'')\n  or (x.kind=''settlement'' and (p_refund_id is not null or p_receipt_id is null))\n  or (x.kind<>''settlement'' and p_refund_id is null)\n  or (p_state=''succeeded'' and (p_receipt_status is null or p_receipt_status not in (''unknown'',''pending'',''succeeded'',''canceled'')))\n  or (p_state<>''succeeded'' and p_receipt_status is not null)\n  or (p_state=''succeeded'' and p_receipt_status<>''unknown'' and p_receipt_id is null)\n  or (x.kind=''settlement'' and p_state=''succeeded'' and p_receipt_status is distinct from ''succeeded'') then\n  raise exception ''fiscal result invalid'' using errcode=''22023''; end if;\n conflict:=(s.provider_refund_id is not null and s.provider_refund_id is distinct from p_refund_id)\n  or (s.provider_receipt_id is not null and p_receipt_id is not null and s.provider_receipt_id<>p_receipt_id)\n  or (s.state in (''succeeded'',''canceled'',''rejected'') and p_state in (''succeeded'',''canceled'') and s.state<>p_state)\n  or (s.receipt_status in (''succeeded'',''canceled'') and p_receipt_status in (''succeeded'',''canceled'') and s.receipt_status<>p_receipt_status);\n if coalesce(conflict,false) then\n  update public.billing_subscription_fiscal_operation_status set requires_review=true,checked_at=clock_timestamp() where command_id=x.command_id;\n  return ''review''; end if;\n -- Late pending/unknown must never undo a terminal monetary or receipt result.\n if s.state in (''succeeded'',''canceled'',''rejected'') and p_state=''pending'' then return s.state; end if;\n next_receipt:=case when s.receipt_status in (''succeeded'',''canceled'') then s.receipt_status\n  when s.receipt_status=''pending'' and p_receipt_status=''unknown'' then s.receipt_status else p_receipt_status end;\n begin\n  update public.billing_subscription_fiscal_operation_status set state=p_state,receipt_status=next_receipt,\n   provider_refund_id=coalesce(s.provider_refund_id,p_refund_id),provider_receipt_id=coalesce(s.provider_receipt_id,p_receipt_id),\n   checked_at=clock_timestamp(),requires_review=(next_receipt=''canceled'' or (x.kind=''settlement'' and p_state=''canceled'')) is true\n   where command_id=x.command_id;\n exception when unique_violation then\n  update public.billing_subscription_fiscal_operation_status set requires_review=true,checked_at=clock_timestamp() where command_id=x.command_id;\n  return ''review'';\n end;\n return case when next_receipt=''canceled'' or (x.kind=''settlement'' and p_state=''canceled'') then ''review'' else p_state end;\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.require_sandbox_environment()","definition":"CREATE OR REPLACE FUNCTION platform_private.require_sandbox_environment()\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare configured text;\nbegin\n -- The shared row lock serializes accepted operations with operator changes.\n select environment into configured from platform_private.billing_runtime_environment\n where singleton for share;\n if configured is distinct from ''sandbox'' then\n  raise exception ''sandbox environment denied'' using errcode=''42501'';\n end if;\nend;\n$function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.require_sandbox_projection()","definition":"CREATE OR REPLACE FUNCTION platform_private.require_sandbox_projection()\n RETURNS void\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nbegin\n if not exists(select 1 from platform_private.billing_runtime_environment\n  where singleton and environment=''sandbox'') then\n  raise exception ''sandbox environment denied'' using errcode=''42501'';\n end if;\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.reserve_subscription_fiscal_operation(uuid,uuid,bigint,text,bigint)","definition":"CREATE OR REPLACE FUNCTION platform_private.reserve_subscription_fiscal_operation(p_order_id uuid, p_command_id uuid, p_expected_version bigint, p_kind text, p_amount_minor bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare o public.billing_sandbox_orders%rowtype; p public.billing_sandbox_payment_results%rowtype;\n l public.billing_subscription_fiscal_ledgers%rowtype; saved public.billing_subscription_fiscal_operations%rowtype;\n r record; receipt jsonb; item jsonb; body jsonb; quantity text; mode text; operation_kind text;\n refunded bigint:=0; refunded_units bigint:=0; remaining bigint; available_units bigint;\n count_units bigint; settled boolean:=false; reserved boolean:=false;\n total numeric; original_amount jsonb; target_amount jsonb;\nbegin\n perform platform_private.require_sandbox_environment();\n if p_order_id is null or p_command_id is null or p_expected_version is null or p_expected_version<0\n  or p_expected_version>=9007199254740991 or p_kind is null or p_kind not in (''refund'',''settlement'')\n  or p_amount_minor is null or p_amount_minor<1 or p_amount_minor>9007199254740991 then\n  raise exception ''invalid fiscal command'' using errcode=''22023''; end if;\n select * into o from public.billing_sandbox_orders where id=p_order_id for update;\n if not found then raise exception ''fiscal order unavailable'' using errcode=''55000''; end if;\n select * into saved from public.billing_subscription_fiscal_operations where command_id=p_command_id;\n if found then\n  if saved.order_id<>p_order_id or saved.expected_version<>p_expected_version or saved.amount_minor<>p_amount_minor\n   or (saved.kind=''settlement'')<>(p_kind=''settlement'') then\n   raise exception ''fiscal command conflict'' using errcode=''22023''; end if;\n  return jsonb_build_object(''commandId'',saved.command_id,''expectedVersion'',saved.expected_version,''kind'',saved.kind,\n   ''amountMinor'',saved.amount_minor,''body'',saved.body,''key'',saved.idempotency_key,''sha256'',saved.body_sha256);\n end if;\n -- Historical legacy fiscal operations are not silently imported into this ledger.\n if exists(select 1 from public.billing_sandbox_refunds f where f.order_id=o.id and f.fiscal_command_id is not null\n  and not exists(select 1 from public.billing_subscription_fiscal_operations x\n   join public.billing_subscription_fiscal_operation_status s using(command_id)\n   join public.billing_subscription_fiscal_ledgers linked_ledger on linked_ledger.order_id=x.order_id\n   where x.command_id=f.fiscal_command_id and x.order_id=f.order_id and x.amount_minor=f.amount_minor\n    and linked_ledger.payment_id=f.payment_id and x.kind<>''settlement''\n    and (f.state=s.state or (f.state=''sending'' and s.state=''unknown'')))) then\n  raise exception ''linked fiscal money state mismatch'' using errcode=''55000''; end if;\n if exists(select 1 from public.billing_sandbox_refunds where order_id=o.id and fiscal_command_id is null and state not in (''canceled'',''rejected''))\n  or exists(select 1 from public.billing_prepayment_settlements where order_id=o.id) then\n  raise exception ''legacy fiscal operation exists'' using errcode=''55000''; end if;\n select * into p from public.billing_sandbox_payment_results where order_id=o.id;\n if p.status is distinct from ''succeeded'' or p.paid is distinct from true or p.requires_review is distinct from false\n  or p.shop_id is distinct from o.shop_id or o.currency is distinct from ''RUB''\n  or o.amount_minor not between 1 and 9007199254740991\n  or not exists(select 1 from public.billing_receipt_payment_status s where s.order_id=o.id\n   and s.payment_id=p.payment_id and s.status=''succeeded'')\n  or not exists(select 1 from public.billing_subscription_fiscal_terms t join public.billing_receipt_snapshots x\n   on x.order_id=t.order_id and x.policy_id=t.policy_id join public.billing_fiscal_policy_models m on m.policy_id=t.policy_id\n   where t.order_id=o.id and x.amount_minor=o.amount_minor and x.currency=o.currency\n    and m.model_version=''subscription_access_v1'') then\n  raise exception ''fiscal payment unverified'' using errcode=''55000''; end if;\n if p_kind=''settlement'' and not exists(select 1 from public.billing_subscription_fiscal_terms\n  where order_id=o.id and period_end<=clock_timestamp()) then\n  raise exception ''subscription settlement not due'' using errcode=''55000''; end if;\n select q.body->''receipt'' into receipt from public.billing_receipt_payment_requests q where q.order_id=o.id;\n original_amount:=jsonb_build_object(''value'',(o.amount_minor/100)::text||''.''||lpad((o.amount_minor%100)::text,2,''0''),''currency'',''RUB'');\n if receipt is null or jsonb_typeof(receipt->''items'') is distinct from ''array''\n  or jsonb_array_length(receipt->''items'') is distinct from 1\n  or receipt#>>''{items,0,payment_mode}'' is distinct from ''full_prepayment''\n  or receipt#>>''{items,0,payment_subject}'' is distinct from ''service''\n  or coalesce(receipt#>>''{items,0,quantity}'','''') not in (''1'',''1.000'',''1.000000'')\n  or receipt#>''{items,0,amount}'' is distinct from original_amount then\n  raise exception ''fiscal source receipt invalid'' using errcode=''55000''; end if;\n select * into l from public.billing_subscription_fiscal_ledgers where order_id=o.id;\n if not found then\n  if p_expected_version<>0 then raise exception ''fiscal version changed'' using errcode=''55000''; end if;\n  insert into public.billing_subscription_fiscal_ledgers(order_id,payment_id,amount_minor)\n   values(o.id,p.payment_id,o.amount_minor) returning * into l;\n end if;\n if l.version<>p_expected_version or l.payment_id<>p.payment_id or l.amount_minor<>o.amount_minor then\n  raise exception ''fiscal version changed'' using errcode=''55000''; end if;\n for r in select x.*,s.state,s.receipt_status from public.billing_subscription_fiscal_operations x\n  left join public.billing_subscription_fiscal_operation_status s on s.command_id=x.command_id\n  where x.order_id=o.id order by x.expected_version loop\n  if r.state is null or r.state in (''reserved'',''unknown'',''pending'')\n   or (r.state=''succeeded'' and r.receipt_status<>''succeeded'')\n   or (r.kind=''settlement'' and r.state in (''canceled'',''rejected'')) then reserved:=true; end if;\n  if r.state=''succeeded'' then\n   if r.kind=''settlement'' then settled:=true;\n   else refunded:=refunded+r.amount_minor; refunded_units:=refunded_units+r.quantity_units; end if;\n  end if;\n end loop;\n if reserved then raise exception ''fiscal operation unresolved'' using errcode=''55000''; end if;\n remaining:=o.amount_minor-refunded; available_units:=1000000-refunded_units;\n if remaining<=0 or available_units<=0 or refunded<0 or refunded_units<0\n  or p_amount_minor>remaining or (p_kind=''settlement'' and (settled or p_amount_minor<>remaining)) then\n  raise exception ''fiscal amount unavailable'' using errcode=''55000''; end if;\n if p_kind=''refund'' and p_amount_minor<remaining and (p_amount_minor<100 or remaining-p_amount_minor<100) then\n  raise exception ''fiscal refund limits'' using errcode=''22023''; end if;\n -- numeric intermediates avoid overflowing bigint during multiplication.\n total:=o.amount_minor::numeric;\n count_units:=case when p_amount_minor=remaining then available_units\n  else floor((2*p_amount_minor::numeric*1000000+total)/(2*total))::bigint end;\n if count_units<1 or count_units>available_units\n  or floor((2*total*count_units+1000000)/2000000)<>p_amount_minor\n  or floor((2*total*(available_units-count_units)+1000000)/2000000)<>remaining-p_amount_minor then\n  raise exception ''fiscal quantity unrepresentable'' using errcode=''22023''; end if;\n mode:=case when p_kind=''settlement'' or settled then ''full_payment'' else ''full_prepayment'' end;\n operation_kind:=case when p_kind=''settlement'' then ''settlement'' when settled then ''refund_after'' else ''refund_before'' end;\n quantity:=(count_units/1000000)::text||''.''||lpad((count_units%1000000)::text,6,''0'');\n item:=(receipt->''items''->0)||jsonb_build_object(''quantity'',quantity,''payment_mode'',mode);\n target_amount:=jsonb_build_object(''value'',(p_amount_minor/100)::text||''.''||lpad((p_amount_minor%100)::text,2,''0''),''currency'',''RUB'');\n body:=case when p_kind=''settlement'' then jsonb_build_object(''type'',''payment'',''payment_id'',p.payment_id,''send'',true,\n  ''customer'',receipt->''customer'',''items'',jsonb_build_array(item),''settlements'',jsonb_build_array(jsonb_build_object(''type'',''prepayment'',''amount'',target_amount)))\n when p_amount_minor=o.amount_minor then jsonb_build_object(''payment_id'',p.payment_id,''amount'',target_amount)\n else jsonb_build_object(''payment_id'',p.payment_id,''amount'',target_amount,\n  ''receipt'',jsonb_build_object(''customer'',receipt->''customer'',''items'',jsonb_build_array(item))) end;\n insert into public.billing_subscription_fiscal_operations(command_id,order_id,expected_version,kind,amount_minor,quantity_units,body,body_sha256)\n values(p_command_id,o.id,l.version,operation_kind,p_amount_minor,count_units,body,\n  encode(extensions.digest(convert_to(body::text,''UTF8''),''sha256''),''hex'')) returning * into saved;\n insert into public.billing_subscription_fiscal_operation_status(command_id) values(p_command_id);\n update public.billing_subscription_fiscal_ledgers set version=version+1 where order_id=o.id;\n return jsonb_build_object(''commandId'',saved.command_id,''expectedVersion'',saved.expected_version,''kind'',saved.kind,\n  ''amountMinor'',saved.amount_minor,''body'',saved.body,''key'',saved.idempotency_key,''sha256'',saved.body_sha256);\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.run_scheduled_sandbox_orders()","definition":"CREATE OR REPLACE FUNCTION platform_private.run_scheduled_sandbox_orders()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare item record; token text; request_id bigint; signed_at text; signature text; sent integer:=0; stopped integer:=0;\nbegin\n perform platform_private.require_sandbox_environment();\n raise exception ''production scheduler binding unconfigured'' using errcode=''55000'';\n if not pg_try_advisory_xact_lock(24092026,7) then return jsonb_build_object(''busy'',true); end if;\n for item in\n  select q.*,o.period_start,o.state as order_state,p.status as payment_status,p.paid,p.requires_review,\n   f.state as fulfillment_state,\n   exists(select 1 from public.billing_sandbox_application_scope a where a.organization_id=o.organization_id) as in_scope\n  from public.billing_sandbox_scheduled_orders q\n  join public.billing_sandbox_orders o on o.id=q.order_id\n  left join public.billing_sandbox_payment_results p on p.order_id=o.id\n  left join public.billing_sandbox_fulfillments f on f.order_id=o.id\n  where q.enabled order by greatest(q.next_check_at,q.not_before,o.period_start),q.order_id limit 5 for update of q skip locked\n loop\n  if item.fulfillment_state=''applied'' or item.fulfillment_state=''review''\n     or clock_timestamp()>=item.expires_at or item.attempts>=6\n     or not item.in_scope or item.payment_status is distinct from ''succeeded''\n     or item.paid is distinct from true or item.requires_review is distinct from false then\n   update public.billing_sandbox_scheduled_orders set enabled=false,stop_reason=case\n    when item.fulfillment_state=''applied'' then ''applied''\n    when item.fulfillment_state=''review'' then ''review''\n    when clock_timestamp()>=item.expires_at then ''expired''\n    when item.attempts>=6 then ''attempt_limit'' else ''ineligible'' end where order_id=item.order_id;\n   stopped:=stopped+1;\n   continue;\n  end if;\n  if clock_timestamp()<greatest(item.not_before,item.period_start,item.next_check_at) then continue; end if;\n  if token is null then\n   select decrypted_secret into token from vault.decrypted_secrets where name=NULL::text;\n   if token is null or token !~ ''^[a-f0-9]{64}$'' then raise exception ''scheduler token unavailable'' using errcode=''55000''; end if;\n  end if;\n\n  signed_at:=floor(extract(epoch from clock_timestamp()))::bigint::text;\n  signature:=encode(extensions.hmac(''qvesta-order-reconcile-v1''||chr(10)||item.order_id::text||chr(10)||signed_at,token,''sha256''),''hex'');\n  select net.http_post(\n   url:=NULL::text,\n   headers:=jsonb_build_object(''Content-Type'',''application/json'',''x-qvesta-order-signature'',signature,''x-qvesta-order-timestamp'',signed_at,''x-qvesta-order-id'',item.order_id::text),\n   body:=''{}''::jsonb,timeout_milliseconds:=45000) into request_id;\n  update public.billing_sandbox_scheduled_orders set attempts=attempts+1,last_request_id=request_id,\n   next_check_at=clock_timestamp()+interval ''5 minutes'' where order_id=item.order_id;\n  sent:=sent+1;\n end loop;\n return jsonb_build_object(''busy'',false,''sent'',sent,''stopped'',stopped);\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.run_scheduled_subscription_settlements()","definition":"CREATE OR REPLACE FUNCTION platform_private.run_scheduled_subscription_settlements()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare item record; token text; signed_at text; signature text; request_id bigint; sent integer:=0; reason text;\nbegin\n perform platform_private.require_sandbox_environment();\n raise exception ''production scheduler binding unconfigured'' using errcode=''55000'';\n if not pg_try_advisory_xact_lock(30092026,3) then return jsonb_build_object(''busy'',true); end if;\n for item in select q.*,s.status,s.requires_review from public.billing_sandbox_settlement_schedule q\n left join public.billing_prepayment_settlement_status s on s.order_id=q.order_id\n where q.enabled order by q.next_check_at,q.order_id limit 5 for update of q skip locked\n loop\n  reason:=case when item.requires_review or item.status=''canceled'' then ''review''\n   when item.status=''succeeded'' then ''succeeded''\n   when clock_timestamp()>=item.expires_at then ''expired''\n   when item.attempts>=6 then ''attempt_limit'' else null end;\n  if reason is null and clock_timestamp()<greatest(item.period_end,item.next_check_at) then continue; end if;\n  if reason is null and not platform_private.settlement_schedule_eligible(item.order_id) then reason:=''ineligible''; end if;\n  if reason is not null then\n   update public.billing_sandbox_settlement_schedule set enabled=false,stop_reason=reason where order_id=item.order_id;\n   continue;\n  end if;\n  if token is null then\n   select decrypted_secret into token from vault.decrypted_secrets where name=NULL::text;\n   if token is null or token !~ ''^[a-f0-9]{64}$'' then raise exception ''scheduler token unavailable''; end if;\n  end if;\n  signed_at:=floor(extract(epoch from clock_timestamp()))::bigint::text;\n  signature:=encode(extensions.hmac(''qvesta-order-settlement-v1''||chr(10)||item.order_id::text||chr(10)||signed_at,token,''sha256''),''hex'');\n  select net.http_post(url:=NULL::text,\n   headers:=jsonb_build_object(''Content-Type'',''application/json'',''x-qvesta-order-id'',item.order_id::text,\n    ''x-qvesta-order-timestamp'',signed_at,''x-qvesta-order-signature'',signature),body:=''{}''::jsonb,timeout_milliseconds:=45000) into request_id;\n  update public.billing_sandbox_settlement_schedule set attempts=attempts+1,last_request_id=request_id,\n   next_check_at=clock_timestamp()+interval ''5 minutes'' where order_id=item.order_id;\n  sent:=sent+1;\n end loop;\n return jsonb_build_object(''busy'',false,''sent'',sent);\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"platform_private.schedule_confirmed_period_after_trial(uuid)","definition":"CREATE OR REPLACE FUNCTION platform_private.schedule_confirmed_period_after_trial(p_order_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare c public.billing_discount_checkouts%rowtype; o public.billing_sandbox_offers%rowtype;\n s public.organization_subscriptions%rowtype; g public.billing_trial_access%rowtype; terms jsonb;\nbegin\n perform platform_private.require_sandbox_environment();\n select * into c from public.billing_discount_checkouts where id=p_order_id;\n if not found or ((c.quote->>''amount_minor'')::bigint is distinct from 0 and not platform_private.has_verified_discount_payment(p_order_id)) then raise exception ''zero trial checkout required'' using errcode=''55000''; end if;\n select * into o from public.billing_sandbox_offers where id=c.offer_id;\n select * into s from public.organization_subscriptions where organization_id=c.organization_id for update;\n terms:=c.quote->''trial_purchase'';\n if terms->>''transition'' is distinct from ''after_trial'' then raise exception ''scheduled trial purchase required'' using errcode=''55000''; end if;\n if s.revision is distinct from o.expected_revision or s.revision is distinct from (terms->>''subscription_revision'')::bigint then raise exception ''billing revision conflict'' using errcode=''40001''; end if;\n select * into g from public.billing_trial_access where id=s.trial_access_id for update;\n if g.id is null or g.id is distinct from (terms->>''access_id'')::uuid\n or g.generation is distinct from (terms->>''generation'')::integer or g.state not in (''scheduled'',''active'')\n or not public.trial_access_matches(s,g) or clock_timestamp()<g.starts_at or clock_timestamp()>=g.ends_at\n or o.period_start is distinct from g.ends_at or o.period_start is distinct from (terms->>''trial_ends_at'')::timestamptz then\n raise exception ''trial checkout context changed'' using errcode=''40001''; end if;\n if (select plan_key from public.billing_plan_versions where id=g.plan_version_id) is distinct from\n (select plan_key from public.billing_plan_versions where id=o.plan_version_id) then raise exception ''same trial plan required'' using errcode=''22023''; end if;\n insert into public.billing_trial_paid_periods(order_id,access_id,organization_id,generation,plan_version_id,period_start,period_end)\n values(p_order_id,g.id,s.organization_id,g.generation,o.plan_version_id,o.period_start,o.period_end);\n return jsonb_build_object(''organization_id'',s.organization_id,''revision'',s.revision,''confirmation_id'',p_order_id,\n ''period_start'',o.period_start,''period_end'',o.period_end,''access_state'',''scheduled'',''trial_remaining_preserved'',true);\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"public.advance_organization_trial(uuid)","definition":"CREATE OR REPLACE FUNCTION public.advance_organization_trial(p_organization_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare s public.organization_subscriptions%rowtype; e public.organization_subscriptions%rowtype;\n g public.billing_trial_access%rowtype; outcome text; before_state jsonb;\nbegin\n if current_setting(''transaction_isolation'')<>''read committed'' then\n   raise exception ''trial requires read committed'' using errcode=''40001''; end if;\n if exists(select 1 from platform_private.active_trial_paid_periods where organization_id=p_organization_id) then\n   perform platform_private.require_sandbox_environment(); end if; select * into s from public.organization_subscriptions where organization_id=p_organization_id for update;\n if not found then return jsonb_build_object(''changed'',false); end if;\n select * into g from public.billing_trial_access where organization_id=p_organization_id and state in (''scheduled'',''active'');\n if not found then return jsonb_build_object(''changed'',false); end if;\n before_state:=to_jsonb(s);\n if s.trial_access_id is distinct from g.id or not public.trial_access_matches(s,g) then\n   if g.was_started or exists(select 1 from public.billing_trial_transitions where access_id=g.id and kind=''active'') then\n      outcome:=''finished'';\n    else outcome:=''review''; end if;\n else\n   e:=public.effective_trial_subscription(s,clock_timestamp());\n   if e.status in (''free'',''active'') then outcome:=''finished'';\n   elsif e.status=''trial'' and g.state=''scheduled'' then outcome:=''active'';\n   else return jsonb_build_object(''changed'',false); end if;\n   update public.organization_subscriptions set status=e.status,plan_version_id=e.plan_version_id,\n     period_start=e.period_start,period_end=e.period_end,cancel_at_period_end=false,\n     scheduled_plan_version_id=null,scheduled_effective_at=null,\n     trial_access_id=case when outcome=''finished'' then null else g.id end\n     where organization_id=p_organization_id returning * into s;\n end if;\n update public.billing_trial_access set state=outcome where id=g.id;\n insert into public.billing_trial_transitions(access_id,kind,before_state,after_state,generation)\n   values(g.id,outcome,before_state,to_jsonb(s),g.generation) on conflict(access_id,kind,generation) do nothing;\n return jsonb_build_object(''changed'',true,''outcome'',outcome,''access_id'',g.id);\nend;\n$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"public.apply_sandbox_payment_event(uuid,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.apply_sandbox_payment_event(p_event_id uuid, p_payment jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare e public.billing_sandbox_events%rowtype; o public.billing_sandbox_orders%rowtype; r jsonb; outcome jsonb; v_state text; v_reason text;\nbegin\n perform platform_private.require_sandbox_environment();\n if current_setting(''transaction_isolation'')<>''read committed'' then raise exception ''sandbox requires read committed'' using errcode=''40001''; end if;\n select * into e from public.billing_sandbox_events where id=p_event_id;\n if not found then raise exception ''sandbox event missing'' using errcode=''22023''; end if;\n select * into o from public.billing_sandbox_orders where id=e.order_id;\n -- Порядок: confirmation advisory → подписка → заказ → событие.\n perform pg_advisory_xact_lock(hashtextextended(o.id::text,7350));\n perform 1 from public.organization_subscriptions where organization_id=o.organization_id for update;\n select * into o from public.billing_sandbox_orders where id=e.order_id for update;\n select * into e from public.billing_sandbox_events where id=p_event_id for update;\n if (p_payment->>''paymentId'')::uuid is distinct from e.payment_id then raise exception ''sandbox event payment mismatch'' using errcode=''22023''; end if;\n r:=public.record_sandbox_payment_result_internal(o.id,e.payment_id,p_payment->>''status'',(p_payment->>''paid'')::boolean,(p_payment->>''test'')::boolean,p_payment->>''confirmationUrl'');\n if (r->>''requires_review'')::boolean then v_state:=''review'';v_reason:=''payment_conflict'';\n elsif r->>''status''=''succeeded'' and platform_private.subscription_refund_replay_resolved(o.id) then\n v_state:=''not_paid'';v_reason:=''subscription_refunded'';\n update public.billing_sandbox_orders set state=''finished'' where id=o.id;\n elsif r->>''status'' in (''succeeded'',''canceled'') and exists(select 1 from public.billing_discount_payment_links where payment_order_id=o.id) then\n outcome:=platform_private.process_discount_payment(o.id); v_state:=outcome->>''state'';v_reason:=outcome->>''reason'';\n elsif r->>''status''=''succeeded'' then\n  if not exists(select 1 from public.billing_sandbox_application_scope where organization_id=o.organization_id) then\n   v_state:=''review'';v_reason:=''sandbox_scope_disabled'';\n  else\n   perform public.enqueue_billing_confirmation(o.organization_id,o.id,o.expected_revision,o.plan_version_id,o.period_start,o.period_end);\n   outcome:=public.process_billing_confirmation(o.id);\n   v_state:=outcome->>''state'';v_reason:=outcome->>''reason'';\n  end if;\n else v_state:=''not_paid''; end if;\n insert into public.billing_sandbox_fulfillments(order_id,state,reason) values(o.id,v_state,v_reason)\n on conflict(order_id) do update set state=excluded.state,reason=excluded.reason,checked_at=clock_timestamp();\n if v_state=''applied'' then update public.billing_sandbox_orders set state=''finished'' where id=o.id; end if;\n perform platform_private.bind_sandbox_recurring_method(o.id,p_payment); update public.billing_sandbox_events set processed_at=clock_timestamp() where order_id=o.id and payment_id=e.payment_id;\n return jsonb_build_object(''orderId'',o.id,''paymentStatus'',r->>''status'',''fulfillmentState'',v_state,''reason'',v_reason);\nend;$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"public.begin_sandbox_payment_send(uuid)","definition":"CREATE OR REPLACE FUNCTION public.begin_sandbox_payment_send(p_order_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare o public.billing_sandbox_orders%rowtype; s public.organization_subscriptions%rowtype; org uuid; measured timestamptz;\nbegin\n perform platform_private.require_sandbox_environment();\n select organization_id into org from public.billing_sandbox_orders where id=p_order_id;\n if auth.uid() is null or org is null or not public.has_organization_permission(org,''billing.manage'') then raise exception ''billing management denied'' using errcode=''42501''; end if;\n if current_setting(''transaction_isolation'')<>''read committed'' then raise exception ''sandbox requires read committed'' using errcode=''40001''; end if;\n select * into s from public.organization_subscriptions where organization_id=org for update;\n select * into o from public.billing_sandbox_orders where id=p_order_id for update;\n if not public.has_organization_permission(org,''billing.manage'') then raise exception ''billing management denied'' using errcode=''42501''; end if;\n if exists(select 1 from public.billing_sandbox_payment_results where order_id=o.id) then return jsonb_build_object(''can_send'',false,''reason'',''payment_already_identified''); end if; measured:=clock_timestamp();\n if o.state in (''review'',''finished'') then return jsonb_build_object(''can_send'',false,''reason'',''payment_reconciliation_required''); end if;\n if o.first_sent_at is null and exists(select 1 from platform_private.active_trial_paid_periods where access_id=s.trial_access_id and order_id<>o.id) then\n raise exception ''trial paid period already scheduled'' using errcode=''22023''; end if;\n if o.first_sent_at is null and s.revision<>o.expected_revision then\n   raise exception ''billing revision conflict'' using errcode=''40001''; end if;\n if o.first_sent_at is not null and measured>=o.first_sent_at+interval ''23 hours'' then\n   update public.billing_sandbox_orders set state=''review'' where id=o.id;\n   return jsonb_build_object(''can_send'',false,''reason'',''payment_reconciliation_required'');\n end if;\n insert into public.billing_recurring_send_settings(order_id,save_payment_method)\n values(o.id,o.first_sent_at is null and exists(select 1 from public.billing_recurring_consents c where c.order_id=o.id and not exists(select 1 from public.billing_recurring_revocations r where r.consent_id=c.id))) on conflict(order_id) do nothing; update public.billing_sandbox_orders set first_sent_at=coalesce(first_sent_at,measured),state=''sending'' where id=o.id returning * into o;\n return jsonb_build_object(''can_send'',true,''order'',jsonb_build_object(''id'',o.id,''organizationId'',o.organization_id,''planVersionId'',o.plan_version_id,\n ''environment'',''sandbox'',''shopId'',o.shop_id,''returnUrl'',o.return_url,''amountMinor'',o.amount_minor,''currency'',o.currency,''idempotencyKey'',o.idempotency_key,''firstSentAt'',o.first_sent_at,''savePaymentMethod'',(select save_payment_method from public.billing_recurring_send_settings where order_id=o.id)));\nend;$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"public.begin_sandbox_refund(uuid)","definition":"CREATE OR REPLACE FUNCTION public.begin_sandbox_refund(p_refund_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare r public.billing_sandbox_refunds%rowtype; snapshot jsonb;\nbegin\n perform platform_private.require_sandbox_environment();\n snapshot:=public.read_sandbox_refund(p_refund_id);\n -- Общая блокировка заказа сериализует резервирование суммы и начало отправки.\n perform 1 from public.billing_sandbox_orders where id=(snapshot->''refund''->>''order_id'')::uuid for update;\n select * into r from public.billing_sandbox_refunds where id=p_refund_id for update;\n if exists(select 1 from public.platform_refund_commands where refund_id=r.id) then\n   perform platform_private.check_confirmed_refund_payment(r.id);\n  else\n   perform public.preview_sandbox_refund(r.order_id);\n  end if;\n if r.provider_refund_id is not null or r.state in (''succeeded'',''canceled'',''rejected'',''review'') then return jsonb_build_object(''can_send'',false); end if;\n if r.first_sent_at is not null and clock_timestamp()>=r.first_sent_at+interval ''23 hours'' then\n  update public.billing_sandbox_refunds set state=''review'',updated_at=clock_timestamp() where id=r.id;\n  return jsonb_build_object(''can_send'',false);\n end if;\n update public.billing_sandbox_refunds set state=''sending'',first_sent_at=coalesce(first_sent_at,clock_timestamp()),updated_at=clock_timestamp() where id=r.id;\n return jsonb_build_object(''can_send'',true,''snapshot'',public.read_sandbox_refund(r.id));\nend;$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"public.claim_prepayment_settlement(uuid)","definition":"CREATE OR REPLACE FUNCTION public.claim_prepayment_settlement(p_order_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare prepared jsonb; s public.billing_prepayment_settlement_status%rowtype;\nbegin\n perform platform_private.require_sandbox_environment();\n perform 1 from public.billing_sandbox_orders where id=p_order_id for update;\n if not found then raise exception ''settlement unavailable'' using errcode=''55000''; end if;\n select * into s from public.billing_prepayment_settlement_status where order_id=p_order_id;\n if found then\n  select jsonb_build_object(''body'',r.body,''shopId'',o.shop_id) into prepared\n   from public.billing_prepayment_settlements r join public.billing_sandbox_orders o on o.id=r.order_id where r.order_id=p_order_id;\n  return prepared||jsonb_build_object(''action'',''reconcile'',''receiptId'',s.provider_receipt_id,''status'',s.status,''requiresReview'',s.requires_review);\n end if;\n prepared:=public.prepare_prepayment_settlement(p_order_id);\n insert into public.billing_prepayment_settlement_status(order_id) values(p_order_id) returning * into s;\n return prepared||jsonb_build_object(''action'',''send'',''firstSentAt'',s.first_sent_at,''shopId'',(select shop_id from public.billing_sandbox_orders where id=p_order_id));\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false]],"owner":"postgres","signature":"public.effective_trial_subscription(public.organization_subscriptions,timestamptz)","definition":"CREATE OR REPLACE FUNCTION public.effective_trial_subscription(s public.organization_subscriptions, p_at timestamp with time zone)\n RETURNS public.organization_subscriptions\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare g public.billing_trial_access%rowtype; paid public.billing_trial_paid_periods%rowtype;\nbegin\n if s.trial_access_id is null then return s; end if;\n select * into g from public.billing_trial_access where id=s.trial_access_id;\n if g.state not in (''scheduled'',''active'') or not public.trial_access_matches(s,g) or p_at<g.starts_at then return s; end if;\n select * into paid from platform_private.active_trial_paid_periods where access_id=g.id and generation=g.generation;\n if found and p_at>=paid.period_start then perform platform_private.require_sandbox_projection();\n s.status:=''active''; s.plan_version_id:=paid.plan_version_id; s.period_start:=paid.period_start; s.period_end:=paid.period_end;\n s.cancel_at_period_end:=false; s.scheduled_plan_version_id:=null; s.scheduled_effective_at:=null; return s;\n end if; if p_at>=g.ends_at then\n   s.status:=''free''; s.plan_version_id:=platform_private.current_tariff_version(''free'',g.ends_at);\n   if s.plan_version_id is null then raise exception ''free plan unavailable'' using errcode=''P0001''; end if; s.period_start:=null; s.period_end:=null;\n else\n   s.status:=''trial''; s.plan_version_id:=g.plan_version_id; s.period_start:=g.starts_at; s.period_end:=g.ends_at;\n end if;\n s.cancel_at_period_end:=false; s.scheduled_plan_version_id:=null; s.scheduled_effective_at:=null;\n return s;\nend;\n$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"public.record_prepayment_settlement(uuid,text,text)","definition":"CREATE OR REPLACE FUNCTION public.record_prepayment_settlement(p_order_id uuid, p_receipt_id text, p_status text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare s public.billing_prepayment_settlement_status%rowtype;\nbegin\n perform platform_private.require_sandbox_environment();\n select * into s from public.billing_prepayment_settlement_status where order_id=p_order_id for update;\n if not found or p_receipt_id is null or p_receipt_id !~ ''^r[at]-[a-zA-Z0-9-]{1,100}$''\n  or p_status is null or p_status not in (''pending'',''succeeded'',''canceled'') then\n  raise exception ''invalid settlement result'' using errcode=''22023''; end if;\n if s.provider_receipt_id is not null and s.provider_receipt_id<>p_receipt_id then\n  update public.billing_prepayment_settlement_status set requires_review=true where order_id=p_order_id;\n  return;\n end if;\n if s.status in (''succeeded'',''canceled'') and s.status<>p_status then\n  if p_status in (''succeeded'',''canceled'') then\n   update public.billing_prepayment_settlement_status set requires_review=true where order_id=p_order_id;\n  end if;\n  return;\n end if;\n update public.billing_prepayment_settlement_status set provider_receipt_id=p_receipt_id,status=p_status,checked_at=clock_timestamp() where order_id=p_order_id;\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"public.record_sandbox_payment_result(uuid,uuid,text,boolean,boolean,text)","definition":"CREATE OR REPLACE FUNCTION public.record_sandbox_payment_result(p_order_id uuid, p_payment_id uuid, p_status text, p_paid boolean, p_test boolean, p_confirmation_url text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare org uuid;\nbegin\n perform platform_private.require_sandbox_environment();\n perform pg_advisory_xact_lock(hashtextextended(p_order_id::text,7350));\n select organization_id into org from public.billing_sandbox_orders where id=p_order_id for update;\n if auth.uid() is null or org is null or not public.has_organization_permission(org,''billing.manage'') then raise exception ''billing management denied'' using errcode=''42501''; end if;\n return public.record_sandbox_payment_result_internal(p_order_id,p_payment_id,p_status,p_paid,p_test,p_confirmation_url);\nend;$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"public.record_sandbox_refund(uuid,uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.record_sandbox_refund(p_refund_id uuid, p_provider_id uuid, p_status text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare r public.billing_sandbox_refunds%rowtype; snapshot jsonb;\nbegin\n perform platform_private.require_sandbox_environment();\n snapshot:=public.read_sandbox_refund(p_refund_id);\n perform 1 from public.billing_sandbox_orders where id=(snapshot->''refund''->>''order_id'')::uuid for update;\n select * into r from public.billing_sandbox_refunds where id=p_refund_id for update;\n if p_provider_id is null or p_status is null or p_status not in (''pending'',''succeeded'',''canceled'') or r.first_sent_at is null then raise exception ''invalid refund result'' using errcode=''22023''; end if;\n if r.provider_refund_id is not null and r.provider_refund_id<>p_provider_id then raise exception ''refund identity conflict'' using errcode=''22023''; end if;\n if r.state in (''succeeded'',''canceled'') then\n  if p_status<>''pending'' and p_status<>r.state then update public.billing_sandbox_refunds set state=''review'',updated_at=clock_timestamp() where id=r.id returning * into r; end if;\n  return to_jsonb(r);\n end if;\n if r.state in (''review'',''rejected'') then return to_jsonb(r); end if;\n update public.billing_sandbox_refunds set provider_refund_id=p_provider_id,state=p_status,updated_at=clock_timestamp() where id=r.id returning * into r;\n -- Возврат денег не изменяет подписку, квоты или результаты прохождения.\n return to_jsonb(r);\nend;$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"public.reserve_sandbox_payment_order(uuid,uuid,bigint,uuid,bigint,text,text,timestamptz,timestamptz)","definition":"CREATE OR REPLACE FUNCTION public.reserve_sandbox_payment_order(p_organization_id uuid, p_command_id uuid, p_expected_revision bigint, p_plan_version_id uuid, p_amount_minor bigint, p_shop_id text, p_return_url text, p_period_start timestamp with time zone, p_period_end timestamp with time zone)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare actor uuid:=auth.uid(); s public.organization_subscriptions%rowtype; o public.billing_sandbox_orders%rowtype;\nbegin\n perform platform_private.require_sandbox_environment();\n if actor is null or not public.has_organization_permission(p_organization_id,''billing.manage'') then\n   raise exception ''billing management denied'' using errcode=''42501''; end if;\n if current_setting(''transaction_isolation'')<>''read committed'' then raise exception ''sandbox requires read committed'' using errcode=''40001''; end if;\n if p_command_id is null or p_expected_revision is null or p_expected_revision<0 then raise exception ''invalid sandbox command'' using errcode=''22023''; end if;\n perform pg_advisory_xact_lock(hashtextextended(actor::text||'':sandbox:''||p_command_id::text,0));\n select * into s from public.organization_subscriptions where organization_id=p_organization_id for update;\n if not found then raise exception ''billing state missing'' using errcode=''P0001''; end if;\n if not public.has_organization_permission(p_organization_id,''billing.manage'') then raise exception ''billing management denied'' using errcode=''42501''; end if;\n select * into o from public.billing_sandbox_orders where actor_id=actor and command_id=p_command_id;\n if found then\n   if row(o.organization_id,o.expected_revision,o.plan_version_id,o.amount_minor,o.shop_id,o.return_url,o.period_start,o.period_end)\n      is distinct from row(p_organization_id,p_expected_revision,p_plan_version_id,p_amount_minor,p_shop_id,p_return_url,p_period_start,p_period_end) then\n     raise exception ''sandbox command conflict'' using errcode=''22023''; end if;\n   return to_jsonb(o);\n end if;\n if s.revision<>p_expected_revision then raise exception ''billing revision conflict'' using errcode=''40001''; end if;\n if s.status=''transition'' then raise exception ''billing transition requires agreement'' using errcode=''P0001''; end if;\n if not exists(select 1 from public.billing_plan_versions where id=p_plan_version_id and plan_key<>''free'') then\n   raise exception ''invalid sandbox plan'' using errcode=''22023''; end if;\n if not platform_private.tariff_allows_renewal(p_plan_version_id,clock_timestamp(),false) then\n   raise exception ''tariff version no longer current'' using errcode=''22023''; end if;\n if exists(select 1 from public.billing_sandbox_orders where organization_id=p_organization_id and state<>''finished'') then\n   raise exception ''sandbox order already pending'' using errcode=''P0001''; end if;\n insert into public.billing_sandbox_orders(organization_id,actor_id,command_id,expected_revision,plan_version_id,amount_minor,currency,shop_id,return_url,period_start,period_end)\n values(p_organization_id,actor,p_command_id,p_expected_revision,p_plan_version_id,p_amount_minor,''RUB'',p_shop_id,p_return_url,p_period_start,p_period_end) returning * into o;\n return to_jsonb(o);\nend;$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"public.reserve_sandbox_refund(uuid,uuid,bigint)","definition":"CREATE OR REPLACE FUNCTION public.reserve_sandbox_refund(p_order_id uuid, p_command_id uuid, p_amount_minor bigint)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare preview jsonb; prior public.billing_sandbox_refunds%rowtype; result uuid;\nbegin\n perform platform_private.require_sandbox_environment();\n if p_command_id is null or p_amount_minor is null or p_amount_minor<=0 then raise exception ''invalid refund command'' using errcode=''22023''; end if;\n perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||'':refund:''||p_command_id::text,0));\n preview:=public.preview_sandbox_refund(p_order_id);\n select * into prior from public.billing_sandbox_refunds where actor_id=auth.uid() and command_id=p_command_id;\n if found then\n  if prior.order_id<>p_order_id or prior.amount_minor<>p_amount_minor then raise exception ''refund command conflict'' using errcode=''22023''; end if;\n  return prior.id;\n end if;\n if p_amount_minor>(preview->>''available_minor'')::bigint then raise exception ''refund amount exceeded'' using errcode=''22023''; end if;\n insert into public.billing_sandbox_refunds(order_id,actor_id,command_id,amount_minor,payment_id)\n values(p_order_id,auth.uid(),p_command_id,p_amount_minor,(preview->>''payment_id'')::uuid) returning id into result;\n return result;\nend;$function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"public.retry_sandbox_subscription_refund_application(text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.retry_sandbox_subscription_refund_application(p_shop_id text, p_refund_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare org uuid; f public.billing_sandbox_refunds%rowtype; result jsonb;\nbegin\n perform platform_private.require_sandbox_environment();\n select o.organization_id into org from public.billing_sandbox_orders o\n join public.billing_sandbox_refunds x on x.order_id=o.id\n join public.subscription_refund_reservations l on l.refund_id=x.id\n where x.id=p_refund_id and o.shop_id=p_shop_id;\n if not found then raise exception ''subscription refund scope denied'' using errcode=''42501''; end if;\n perform 1 from public.organization_subscriptions where organization_id=org for update;\n perform 1 from public.billing_sandbox_orders o join public.billing_sandbox_refunds x on x.order_id=o.id where x.id=p_refund_id for update of o;\n select * into f from public.billing_sandbox_refunds where id=p_refund_id for update;\n if f.state<>''succeeded'' or f.provider_refund_id is null or f.first_sent_at is null then\n  return jsonb_build_object(''access_state'',''not_applied''); end if;\n result:=platform_private.reconcile_subscription_refund(f.id,f.provider_refund_id,''succeeded'');\n -- Rotate domain failures so a reviewed case cannot starve the limited batch.\n update public.billing_sandbox_refunds set updated_at=clock_timestamp() where id=f.id;\n return result;\nend; $function$\n"},{"acl":[["postgres","EXECUTE",false],["service_role","EXECUTE",false]],"owner":"postgres","signature":"public.subscription_fiscal_worker_gateway(text,text,uuid,uuid,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.subscription_fiscal_worker_gateway(p_shop_id text, p_action text, p_order_id uuid DEFAULT NULL::uuid, p_command_id uuid DEFAULT NULL::uuid, p_result jsonb DEFAULT NULL::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare o public.billing_sandbox_orders%rowtype; x public.billing_subscription_fiscal_operations%rowtype;\n s public.billing_subscription_fiscal_operation_status%rowtype; result jsonb; remaining bigint; version bigint; state text; failures integer;\nbegin\n if p_action=''before_send'' then perform platform_private.require_sandbox_environment(); end if;\n if current_setting(''transaction_isolation'')<>''read committed'' then raise exception ''fiscal worker requires read committed'' using errcode=''40001''; end if;\n if p_shop_id is null or p_shop_id !~ ''^[0-9]+$'' or p_action is null\n  or p_action not in (''claim_settlement'',''read'',''record'',''review'',''poll'',''before_send'')\n  or (p_action=''claim_settlement'' and (p_order_id is null or p_command_id is not null))\n  or (p_action<>''claim_settlement'' and (p_command_id is null or p_order_id is not null)) then\n  raise exception ''invalid fiscal worker context'' using errcode=''42501''; end if;\n if p_action=''claim_settlement'' then select * into o from public.billing_sandbox_orders where id=p_order_id;\n else\n  select * into x from public.billing_subscription_fiscal_operations where command_id=p_command_id;\n  select * into o from public.billing_sandbox_orders where id=x.order_id;\n end if;\n if o.id is null or o.shop_id<>p_shop_id or not exists(select 1 from public.billing_sandbox_application_scope where organization_id=o.organization_id)\n  or not exists(select 1 from public.billing_subscription_fiscal_ledgers where order_id=o.id) then\n  raise exception ''fiscal worker scope denied'' using errcode=''42501''; end if;\n perform 1 from public.organization_subscriptions where organization_id=o.organization_id for update;\n perform 1 from public.billing_sandbox_orders where id=o.id for update;\n if p_action=''claim_settlement'' then\n  select * into x from public.billing_subscription_fiscal_operations where order_id=o.id and kind=''settlement'' order by expected_version limit 1;\n  if not found then\n   select l.amount_minor-coalesce((select sum(q.amount_minor) from public.billing_subscription_fiscal_operations q\n    join public.billing_subscription_fiscal_operation_status z using(command_id) where q.order_id=o.id and q.kind<>''settlement'' and z.state=''succeeded''),0),l.version\n    into remaining,version from public.billing_subscription_fiscal_ledgers l where l.order_id=o.id;\n   perform platform_private.reserve_subscription_fiscal_operation(o.id,gen_random_uuid(),version,''settlement'',remaining);\n   select * into x from public.billing_subscription_fiscal_operations where order_id=o.id and kind=''settlement'';\n  end if;\n  return platform_private.claim_subscription_fiscal_operation(x.command_id)||jsonb_build_object(''commandId'',x.command_id);\n end if;\n select * into s from public.billing_subscription_fiscal_operation_status where command_id=x.command_id for update;\n if s.command_id is null or s.first_sent_at is null\n  or (x.kind<>''settlement'' and not exists(select 1 from public.billing_sandbox_refunds where fiscal_command_id=x.command_id)) then\n  raise exception ''fiscal worker operation unavailable'' using errcode=''55000''; end if;\n if p_action=''read'' then\n  result:=platform_private.claim_subscription_fiscal_operation(x.command_id);\n  if result->>''action''=''send'' then raise exception ''worker cannot send refund'' using errcode=''55000''; end if;\n  return result||jsonb_build_object(''commandId'',x.command_id);\n elsif p_action=''record'' then\n  if p_result->>''commandId'' is distinct from x.command_id::text or p_result->>''shopId'' is distinct from p_shop_id then\n   raise exception ''fiscal result invalid'' using errcode=''22023''; end if;\n  if x.kind<>''settlement'' then return platform_private.record_linked_subscription_fiscal_refund(x.command_id,p_result); end if;\n  state:=platform_private.record_subscription_fiscal_result(x.command_id,(p_result->>''paymentId'')::uuid,p_shop_id,\n   p_result->>''bodySha256'',(p_result->>''amountMinor'')::bigint,p_result->>''state'',(p_result->>''refundId'')::uuid,p_result->>''receiptId'',p_result->>''receiptStatus'');\n  return jsonb_build_object(''state'',state);\n elsif p_action=''review'' then\n  perform platform_private.mark_subscription_fiscal_review(x.command_id,p_result->>''reason'');\n  return jsonb_build_object(''state'',''review'');\n elsif p_action=''poll'' then\n  if jsonb_typeof(p_result->''resolved'') is distinct from ''boolean'' then raise exception ''invalid fiscal poll'' using errcode=''22023''; end if;\n  failures:=case when (p_result->>''resolved'')::boolean then 0 else least(s.poll_failures+1,16) end;\n  update public.billing_subscription_fiscal_operation_status set poll_failures=failures,last_polled_at=clock_timestamp(),\n   next_check_at=clock_timestamp()+make_interval(secs=>case when failures=0 then 300 else least(3600,60*power(2,failures-1))::integer end)\n   where command_id=x.command_id;\n  return jsonb_build_object(''recorded'',true);\n else\n  if x.kind<>''settlement'' or s.state<>''unknown'' or s.requires_review or s.provider_receipt_id is not null\n   or s.first_sent_at<=clock_timestamp()-interval ''23 hours''\n   or p_result->>''key'' is distinct from x.idempotency_key::text or p_result->>''sha256'' is distinct from x.body_sha256\n   or (p_result->>''firstSentAt'')::timestamptz is distinct from s.first_sent_at\n   or not exists(select 1 from public.billing_subscription_fiscal_terms where order_id=o.id and period_end<=clock_timestamp())\n   or exists(select 1 from public.billing_subscription_fiscal_operations q join public.billing_subscription_fiscal_operation_status z using(command_id) where q.order_id=o.id and z.requires_review)\n   or not exists(select 1 from public.billing_sandbox_payment_results p join public.billing_subscription_fiscal_ledgers l on l.order_id=p.order_id\n    where p.order_id=o.id and p.payment_id=l.payment_id and p.shop_id=p_shop_id and p.status=''succeeded'' and p.paid and not p.requires_review) then\n   raise exception ''fiscal worker send denied'' using errcode=''55000''; end if;\n  return jsonb_build_object(''authorized'',true,''commandId'',x.command_id,''key'',x.idempotency_key,''sha256'',x.body_sha256);\n end if;\nend; $function$\n"}],"constraints":[{"conname":"billing_runtime_environment_environment_check","contype":"c","definition":"CHECK ((environment = ANY (ARRAY[''sandbox''::text, ''production''::text])))","convalidated":true},{"conname":"billing_runtime_environment_pkey","contype":"p","definition":"PRIMARY KEY (singleton)","convalidated":true},{"conname":"billing_runtime_environment_singleton_check","contype":"c","definition":"CHECK (singleton)","convalidated":true}]}'::jsonb;
begin
 if to_regclass('platform_private.billing_runtime_environment') is null then
  -- Reject partial installation instead of silently repairing it.
  if to_regprocedure('platform_private.require_sandbox_environment()') is not null
   or to_regprocedure('platform_private.require_sandbox_projection()') is not null
   or to_regprocedure('platform_private.guard_sandbox_period_confirmation()') is not null
   or to_regprocedure('platform_private.check_initial_billing_environment()') is not null
   or to_regprocedure('platform_private.protect_billing_environment_identity()') is not null then
   raise exception 'billing guard partial installation';
  end if;
  execute '-- Candidate migration: deliberately outside automatic migration discovery.
-- Stage initialization and remaining sandbox paths must be reviewed before release.

-- Source hashes from the 324-migration baseline (PostgreSQL 17), CRLF -> LF.
-- Validate every target before rewriting any body; unexpected drift fails closed.
do $baseline$
declare signature text; expected text; actual text;
begin
 for signature,expected in select key,value from jsonb_each_text($hashes$
{
  "platform_private.prepare_subscription_refund_recovery(uuid)": "91067f0ee1b0564f60fd29daec74b8517e7a9e85cdfbc445aac58918f4491c9e",
